"use client";

/**
 * Filter chips writing back into the URL search params.
 */
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, type SelectOption } from "@/components/ui/select";
import { humanizeStatus } from "@/lib/format";
import { activeFilterCount, UNASSIGNED_TOKEN } from "@/hooks/issue-filter-params";
import { ISSUE_STATUSES, type IssueFilter, type IssueStatus } from "@/types/issue";
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";
import type { Project } from "@/types/project";
import type { ProjectId } from "@/types/common";
import type { ReactElement } from "react";

export type IssueFilterBarProps = {
  filter: IssueFilter;
  projects: readonly Project[];
  members: readonly MemberWithUser[];
  onChange: (filter: IssueFilter) => void;
};

/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = filter.status ?? [];
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

export function IssueFilterBar(
  props: IssueFilterBarProps,
): ReactElement | null {
  const { filter, projects, members, onChange } = props;

  const projectOptions: readonly SelectOption[] = [
    { value: "", label: "All projects" },
    ...projects.map((project) => ({
      value: project.id,
      label: project.name,
    })),
  ];

  const assigneeOptions: readonly SelectOption[] = [
    { value: "", label: "Anyone" },
    { value: UNASSIGNED_TOKEN, label: "Unassigned" },
    ...members.map((member) => ({
      value: member.userId,
      label: member.user.name,
    })),
  ];

  return (
    <div className="flex flex-wrap items-center gap-2">
      <Input
        name="q"
        type="search"
        value={filter.query ?? ""}
        placeholder="Search issues"
        onChange={(value) =>
          onChange(value.length === 0 ? stripQuery(filter) : { ...filter, query: value })
        }
      />

      <Select
        name="project"
        value={filter.projectId ?? ""}
        options={projectOptions}
        onChange={(value) =>
          onChange(
            value.length === 0
              ? stripProject(filter)
              : { ...filter, projectId: value as ProjectId },
          )
        }
      />

      <Select
        name="assignee"
        value={
          filter.assigneeId === undefined
            ? ""
            : (filter.assigneeId ?? UNASSIGNED_TOKEN)
        }
        options={assigneeOptions}
        onChange={(value) => onChange(withAssignee(filter, value))}
      />

      <div className="flex flex-wrap gap-1">
        {ISSUE_STATUSES.map((status) => {
          const active = (filter.status ?? []).includes(status);
          return (
            <Button
              key={status}
              variant={active ? "primary" : "ghost"}
              size="sm"
              onClick={() => onChange(toggleStatus(filter, status))}
            >
              {humanizeStatus(status)}
            </Button>
          );
        })}
      </div>

      {activeFilterCount(filter) > 0 ? (
        <Button variant="ghost" size="sm" onClick={() => onChange({})}>
          Clear ({activeFilterCount(filter)})
        </Button>
      ) : null}
    </div>
  );
}

function stripQuery(filter: IssueFilter): IssueFilter {
  const { query: _query, ...rest } = filter;
  return rest;
}

function stripProject(filter: IssueFilter): IssueFilter {
  const { projectId: _projectId, ...rest } = filter;
  return rest;
}

function withAssignee(filter: IssueFilter, raw: string): IssueFilter {
  if (raw.length === 0) {
    const { assigneeId: _assigneeId, ...rest } = filter;
    return rest;
  }
  return {
    ...filter,
    assigneeId: raw === UNASSIGNED_TOKEN ? null : (raw as UserId),
  };
}
/**
 * Declarative navigation tree. Each item names the permission and flag that
 * gate it, which is how the sidebar stays role-aware without ad-hoc
 * conditionals: `visibleNav()` is the only place that decides what a given
 * actor sees, and it decides by calling `can()` and consulting the flag
 * snapshot rather than by branching on `actor.role`.
 */
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import type { FeatureFlagKey, FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { PermissionAction, PermissionResource } from "@/types/permission";

export type NavItem = {
  key: string;
  label: string;
  segment: string;
  icon?: string;
  action?: PermissionAction;
  flag?: FeatureFlagKey;
  children?: readonly NavItem[];
};

export const SIDEBAR_NAV: readonly NavItem[] = [
  {
    key: "overview",
    label: "Overview",
    segment: "",
    icon: "home",
    action: "org:read",
  },
  {
    key: "projects",
    label: "Projects",
    segment: "projects",
    icon: "folder",
    action: "project:read",
  },
  {
    key: "issues",
    label: "Issues",
    segment: "issues",
    icon: "circle-dot",
    action: "issue:read",
    children: [
      {
        key: "issues.assigned",
        label: "Assigned to me",
        segment: "issues?assignee=me",
        action: "issue:read",
      },
      {
        key: "issues.board",
        label: "Board",
        segment: "board",
        action: "issue:read",
        flag: "kanban_board",
      },
      {
        key: "issues.search",
        label: "Advanced search",
        segment: "search",
        action: "issue:read",
        flag: "advanced_search",
      },
    ],
  },
  {
    key: "inbox",
    label: "Inbox",
    segment: "inbox",
    icon: "bell",
    action: "notification:read",
  },
  {
    key: "activity",
    label: "Activity",
    segment: "activity",
    icon: "history",
    action: "activity:read",
    flag: "activity_feed",
  },
  {
    key: "members",
    label: "Members",
    segment: "members",
    icon: "users",
    action: "member:read",
  },
];

export const SETTINGS_NAV: readonly NavItem[] = [
  {
    key: "settings.general",
    label: "General",
    segment: "general",
    action: "org:read",
  },
  {
    key: "settings.members",
    label: "Members",
    segment: "members",
    action: "member:read",
  },
  {
    key: "settings.billing",
    label: "Billing",
    segment: "billing",
    action: "org:manage_billing",
  },
  {
    key: "settings.flags",
    label: "Feature flags",
    segment: "flags",
    action: "org:manage_flags",
  },
  {
    key: "settings.webhooks",
    label: "Webhooks",
    segment: "webhooks",
    action: "webhook:manage",
    flag: "webhooks",
  },
  {
    key: "settings.export",
    label: "Export",
    segment: "export",
    action: "activity:export",
    flag: "csv_export",
  },
];

/**
 * The resource a nav-level permission question is asked about. Nav items are
 * asked "could this actor do this at all in this org?", so the resource is
 * always the actor's own org, shaped for the action's resource kind.
 */
function navResource(action: PermissionAction, actor: Actor): PermissionResource {
  const [domain] = action.split(":");
  switch (domain) {
    case "org":
      return action === "org:manage_billing"
        ? { kind: "billing", orgId: actor.orgId }
        : { kind: "organization", orgId: actor.orgId };
    case "activity":
      return { kind: "activity", orgId: actor.orgId };
    case "notification":
      return { kind: "notification", orgId: actor.orgId, recipientId: actor.userId };
    case "webhook":
      return { kind: "webhook", orgId: actor.orgId, webhookId: null };
    default:
      // member / project / issue / comment nav entries are org-wide questions.
      return { kind: "organization", orgId: actor.orgId };
  }
}

/**
