"use client";

/**
 * Role-aware sidebar: every item is filtered through `can()` and its flag.
 *
 * Must call (do not reimplement): can, isEnabled
 */
import Link from "next/link";
import { SETTINGS_NAV, SIDEBAR_NAV, visibleNav, type NavItem } from "@/config/nav";
import { cn } from "@/lib/cn";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { orgPath, projectPath } from "@/lib/url";
import { orgFlagContext } from "@/hooks/flag-context";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { OrgSwitcher } from "./org-switcher";

export type AppSidebarProps = {
  org: Organization;
  actor: Actor;
  flags: FeatureFlagSnapshot;
  projects: readonly Project[];
  pathname: string;
  /** Orgs offered by the switcher; defaults to just the current one. */
  organizations?: readonly Organization[];
};

/** True when `pathname` is the item's route or lives beneath it. */
export function isActiveSegment(pathname: string, href: string): boolean {
  return pathname === href || pathname.startsWith(`${href}/`);
}

export function AppSidebar(props: AppSidebarProps): ReactElement | null {
  const { org, actor, flags, projects, pathname, organizations } = props;

  // The nav tree declares the permission and flag each item needs; `visibleNav`
  // applies both. Nothing here branches on `actor.role`.
  const context = orgFlagContext(org, actor);
  const primary = visibleNav(SIDEBAR_NAV, actor, flags);
  const settings = visibleNav(SETTINGS_NAV, actor, flags);

  // The project shortcut list is its own gate: reading projects at all, and
  // the public-projects flag for the "shared" affordance.
  const mayReadProjects = can(
    actor,
    "project:read",
    organizationResource(org.id),
  );
  const publicProjectsOn =
    flags.public_projects === true || isEnabled("public_projects", context);

  function renderItem(item: NavItem): ReactElement {
    const href = orgPath(org.slug, item.segment);
    return (
      <li key={item.key}>
        <Link
          href={href}
          className={cn(
            "block rounded px-2 py-1 text-sm",
            isActiveSegment(pathname, href)
              ? "bg-neutral-200 font-medium"
              : "hover:bg-neutral-100",
          )}
        >
          {item.label}
        </Link>
        {item.children !== undefined && item.children.length > 0 ? (
          <ul className="ml-3 mt-0.5 space-y-0.5">
            {item.children.map(renderItem)}
          </ul>
        ) : null}
      </li>
    );
  }

/**
 * An actor from another org cannot read or mutate an issue.
 *
 * Owner C implements `@/server/services/issue-service`; the integration pass
 * fills these in. Seed both tenants with `seedTwoTenants()`.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import * as issueService from "@/server/services/issue-service";
import { TenantScopeError } from "@/lib/tenant";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;
let northIssue: Issue;
let acmeIssue: Issue;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();

  north = await createTenant("scopenorth");
  acme = await createTenant("scopeacme");

  northIssue = await issueService.createIssue(
    north.actors.member,
    issueInput(north.org.id, north.project.id, { title: "Northwind only" }),
  );

  acmeIssue = await issueService.createIssue(
    acme.actors.member,
    issueInput(acme.org.id, acme.project.id, { title: "Acme only" }),
  );
});

afterAll(() => {
  cleanup();
});

describe("services/issue-service — tenant scope", () => {
  it("refuses a read for an actor whose orgId differs from the issue's", async () => {
    await expect(
      issueService.getIssue(acme.actors.member, north.org.id, northIssue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("refuses a cross-tenant read even for the other org's owner", async () => {
    await expect(
      issueService.getIssue(acme.actors.owner, north.org.id, northIssue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("never returns another tenant's issues from a list query", async () => {
    const page = await issueService.listIssues(north.actors.owner, {
      orgId: north.org.id,
      limit: 25,
      cursor: null,
    });

    expect(page.items.map((issue) => issue.title)).not.toContain(acmeIssue.title);
    expect(page.items.every((issue) => issue.orgId === north.org.id)).toBe(true);
  });

  it("maps a cross-tenant mutation to tenant_scope_violation", async () => {
    const error: unknown = await issueService
      .updateIssue(acme.actors.owner, {
        orgId: north.org.id,
        issueId: northIssue.id,
        title: "Hijacked title",
      })
      .catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(TenantScopeError);
    expect((error as TenantScopeError).code).toBe("tenant_scope_violation");
  });
});
/**
 * Every query filters by `orgId` and by `archived_at`.
 *
 * Owner C implements `@/server/repositories/issue-repository`. Seed with
 * `seedTwoTenants()` from `tests/helpers/db.ts` so the negative case is a real
