assert old in s
s=s.replace(old,new)

old='''/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];
'''
new='''/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** Every status that is not closed, in `ISSUE_STATUSES` order. */
export const OPEN_ISSUE_STATUSES: readonly IssueStatus[] = ISSUE_STATUSES.filter(
  (status) => !CLOSED_ISSUE_STATUSES.includes(status),
);

/** Names a filter may use in place of listing the statuses one by one. */
export type IssueStatusGroup = "open" | "closed";

export const ISSUE_STATUS_GROUPS: Readonly<
  Record<IssueStatusGroup, readonly IssueStatus[]>
> = {
  open: OPEN_ISSUE_STATUSES,
  closed: CLOSED_ISSUE_STATUSES,
};

/** One entry of a status filter: a status or a group of statuses. */
export type IssueStatusFilterValue = IssueStatus | IssueStatusGroup;

export const ISSUE_STATUS_FILTER_VALUES: readonly IssueStatusFilterValue[] = [
  ...ISSUE_STATUSES,
  "open",
  "closed",
];

export function isIssueStatusGroup(value: string): value is IssueStatusGroup {
  return Object.hasOwn(ISSUE_STATUS_GROUPS, value);
}

/**
 * Expands the groups in a status filter to their member statuses, dropping
 * duplicates and keeping first-seen order.
 */
export function expandIssueStatuses(
  values: readonly IssueStatusFilterValue[],
): IssueStatus[] {
  const expanded = new Set<IssueStatus>();
  for (const value of values) {
    if (isIssueStatusGroup(value)) {
      for (const status of ISSUE_STATUS_GROUPS[value]) expanded.add(status);
    } else {
      expanded.add(value);
    }
  }
  return [...expanded];
}

