import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueService from "@/server/services/issue-service";
import { issueFilterSchema } from "@/schemas/issue";
import { exportIssuesSchema } from "@/schemas/export";
import { parseIssueFilterParams, issueFilterToParams } from "@/hooks/issue-filter-params";
import { SIDEBAR_NAV } from "@/config/nav";
import { createTenant, issueInput, useTemporaryDatabase } from "$P/tests/server/_support/fixtures";

let cleanup: () => void;
let t: Awaited<ReturnType<typeof createTenant>>;
const ids: Record<string, string> = {};
let bug: string, reg: string;

async function mk(name: string, o: any = {}, labels: string[] = [], status?: any) {
  const n = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  const issue = await issueRepo.insertIssue({ ...issueInput(t.org.id, t.project.id, { title: name, ...o }), labelIds: labels as any }, t.userIds.owner, n);
  if (status) await issueRepo.setIssueStatus(t.org.id, issue.id, status);
  ids[name] = issue.id;
  return issue;
}

async function viaUrl(query: string, actor = t.actors.member) {
  const filter = parseIssueFilterParams(new URLSearchParams(query));
  const input = issueFilterSchema.parse({ ...filter, orgId: t.org.id, limit: 2 });
  const all: string[] = [];
  let cursor: string | null = null;
  let total = -1;
  do {
    const page = await issueService.listIssues(actor, { ...input, cursor });
    total = page.total;
    all.push(...page.items.map((i) => Object.keys(ids).find((k) => ids[k] === i.id)!));
    cursor = page.nextCursor;
  } while (cursor);
  // service with schema accepting raw (unexpanded) vocabulary too
  return { names: all.sort(), total };
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("filters");
  bug = (await labelRepo.insertLabel({ orgId: t.org.id, name: "bug", color: "#ff0000", description: null } as any)).id;
  reg = (await labelRepo.insertLabel({ orgId: t.org.id, name: "regression", color: "#00ff00", description: null } as any)).id;
  await mk("mine", { assigneeId: t.userIds.member, dueAt: "2026-03-05T23:30:00.000Z" }, [bug, reg]);
  await mk("theirs", { assigneeId: t.userIds.admin, dueAt: "2026-03-06T00:00:00.000Z" }, [bug], "done");
  await mk("nobody", { dueAt: "2026-03-05T12:00:00Z" }, [reg], "canceled");
  await mk("nodue", {}, [], "in_review");
  const arch = await mk("archived", { assigneeId: t.userIds.member });
  await issueRepo.archiveIssue(t.org.id, arch.id);
});
afterAll(() => cleanup());

describe("reports", () => {
  it("1 assignee=me", async () => {
    expect(await viaUrl("assignee=me")).toEqual({ names: ["mine"], total: 1 });
    expect(await viaUrl("assignee=me", t.actors.admin)).toEqual({ names: ["theirs"], total: 1 });
    expect(parseIssueFilterParams(new URLSearchParams("assignee=me")).assigneeId).toBe("me");
    expect(await viaUrl("author=me", t.actors.owner)).toEqual({ names: ["mine", "nobody", "nodue", "theirs"], total: 4 });
  });
  it("2 unassigned", async () => {
    expect(await viaUrl("assignee=none")).toEqual({ names: ["nobody", "nodue"], total: 2 });
  });
  it("3 labels all-of", async () => {
    expect(await viaUrl(\`label=\${bug},\${reg}\`)).toEqual({ names: ["mine"], total: 1 });
    expect(await viaUrl(\`label=\${bug}\`)).toEqual({ names: ["mine", "theirs"], total: 2 });
  });
  it("4 due_before", async () => {
    expect(await viaUrl("due_before=2026-03-05")).toEqual({ names: ["mine", "nobody"], total: 2 });
    expect(await viaUrl("due_before=2026-03-06")).toEqual({ names: ["mine", "nobody", "theirs"], total: 3 });
    expect(await viaUrl("due_before=2026-03-05T12:00:00.000Z")).toEqual({ names: [], total: 0 });
    expect(await viaUrl("due_before=2026-03-05T12:00:00.001Z")).toEqual({ names: ["nobody"], total: 1 });
    expect(await viaUrl("due_before=2026-03-06T00:00:00Z")).toEqual({ names: ["mine", "nobody"], total: 2 });
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "2026-03-05" }).success).toBe(true);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "2026-02-30" }).success).toBe(false);
