async function mk(name: string, o: any = {}, labels: string[] = [], status?: any) {
  const n = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  const issue = await issueRepo.insertIssue({ ...issueInput(t.org.id, t.project.id, { title: name, ...o }), labelIds: labels as any }, t.userIds.owner, n);
  if (status) await issueRepo.setIssueStatus(t.org.id, issue.id, status);
  ids[name] = issue.id;
  return issue;
}

